#' Campionamento stratificato
#'
#' 
#' @param data .
#' @param strat_var Una o più variabili categoriali (o numeriche con pochi
#'   livelli) usate per suddividere la popolazione negli M strati. Se ne vengono
#'   fornite più di una, gli strati sono dati dall'incrocio joint dei livelli
#'   (es. Sesso × Fascia di età → 6 strati per 2 × 3 livelli). Le unità
#'   all'interno di ciascuno strato dovrebbero essere omogenee rispetto al
#'   fenomeno di interesse.
#' @param aux_var Variabile quantitativa usata per stimare lo scarto
#'   quadratico medio σ_j dentro ciascuno strato (richiesta per il metodo
#'   ottimale). Tipicamente è la variabile di interesse o una sua proxy.
#' @param id_var Variabile usata per identificare le singole unità nel
#'   dataset. Se specificata, la tabella "Unità estratte" mostra gli ID dei
#'   soggetti selezionati.
#' @param tuto .
#' @param method 'proportional' alloca le unità in proporzione all'ampiezza
#'   dello strato (n_j = N_j · n/N). 'optimal' alloca anche in proporzione alla
#'   variabilità interna σ_j stimata sulla variabile ausiliaria (allocazione di
#'   Neyman).
#' @param size_mode .
#' @param n .
#' @param f .
#' @param seed .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$strata} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$extracted} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$out_freq} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
samplestrat <- function(
    data,
    strat_var,
    aux_var,
    id_var,
    tuto = TRUE,
    method = "proportional",
    size_mode = "n",
    n = 30,
    f = 0.1,
    seed = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("samplestrat requires jmvcore to be installed (restart may be required)")

    if ( ! missing(strat_var)) strat_var <- jmvcore::resolveQuo(jmvcore::enquo(strat_var))
    if ( ! missing(aux_var)) aux_var <- jmvcore::resolveQuo(jmvcore::enquo(aux_var))
    if ( ! missing(id_var)) id_var <- jmvcore::resolveQuo(jmvcore::enquo(id_var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(strat_var), strat_var, NULL),
            `if`( ! missing(aux_var), aux_var, NULL),
            `if`( ! missing(id_var), id_var, NULL))


    options <- samplestratOptions$new(
        strat_var = strat_var,
        aux_var = aux_var,
        id_var = id_var,
        tuto = tuto,
        method = method,
        size_mode = size_mode,
        n = n,
        f = f,
        seed = seed)

    analysis <- samplestratClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

